create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text check(char_length(display_name)<=80),created_at timestamptz not null default now());
create table if not exists public.monitored_servers(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(name) between 1 and 80),host text not null check(char_length(host) between 1 and 255),port integer not null default 19132 check(port between 1 and 65535),edition text not null default 'bedrock' check(edition='bedrock'),enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.status_checks(id bigint generated always as identity primary key,server_id uuid not null references public.monitored_servers(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,state text not null check(state in('online','offline','unknown')),players_online integer check(players_online is null or players_online>=0),players_max integer check(players_max is null or players_max>=0),latency_ms integer check(latency_ms is null or latency_ms>=0),source text not null default 'provider' check(source in('provider','error','unconfigured')),message text check(message is null or char_length(message)<=500),checked_at timestamptz not null default now());
create table if not exists public.start_requests(id uuid primary key default gen_random_uuid(),server_id uuid not null references public.monitored_servers(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,message text not null check(char_length(message) between 1 and 500),requested_for timestamptz,status text not null default 'pending' check(status in('pending','acknowledged','cancelled','completed')),created_at timestamptz not null default now());
create index if not exists servers_user_idx on public.monitored_servers(user_id);
create index if not exists checks_server_time_idx on public.status_checks(server_id,checked_at desc);
create index if not exists requests_user_time_idx on public.start_requests(user_id,created_at desc);
alter table public.profiles enable row level security;alter table public.monitored_servers enable row level security;alter table public.status_checks enable row level security;alter table public.start_requests enable row level security;
create policy profiles_select_own on public.profiles for select to authenticated using(auth.uid()=id);
create policy profiles_insert_own on public.profiles for insert to authenticated with check(auth.uid()=id);
create policy profiles_update_own on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
create policy servers_select_own on public.monitored_servers for select to authenticated using(auth.uid()=user_id);
create policy servers_insert_own on public.monitored_servers for insert to authenticated with check(auth.uid()=user_id);
create policy servers_update_own on public.monitored_servers for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy servers_delete_own on public.monitored_servers for delete to authenticated using(auth.uid()=user_id);
create policy checks_select_own on public.status_checks for select to authenticated using(auth.uid()=user_id);
create policy checks_insert_own on public.status_checks for insert to authenticated with check(auth.uid()=user_id);
create policy requests_select_own on public.start_requests for select to authenticated using(auth.uid()=user_id);
create policy requests_insert_own on public.start_requests for insert to authenticated with check(auth.uid()=user_id);
create policy requests_update_own on public.start_requests for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy requests_delete_own on public.start_requests for delete to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now();return new;end; $$;
create trigger monitored_servers_updated_at before update on public.monitored_servers for each row execute function public.set_updated_at();
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'name','')) on conflict(id) do nothing;return new;end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();